import time


def retry(times, exceptions=(Exception,), delay=0.0, backoff=2.0, sleep=time.sleep):
    """Retry the decorated function when it raises one of ``exceptions``.

    The function is called at most ``times`` times. After failed attempt ``n``
    (counting from 1) it waits ``delay * backoff ** (n - 1)`` seconds via ``sleep``.
    The wrapper exposes ``last_attempts``, the call count of the latest invocation.
    """
    if times < 1:
        raise ValueError(f"times must be >= 1, got {times}")
    if delay < 0:
        raise ValueError(f"delay must be >= 0, got {delay}")
    if backoff < 1:
        raise ValueError(f"backoff must be >= 1, got {backoff}")

    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            for attempt in range(1, times + 1):
                wrapper.last_attempts = attempt
                try:
                    return func(*args, **kwargs)
                except exceptions:
                    if attempt == times:
                        raise
                    if delay:
                        sleep(delay * backoff ** (attempt - 1))

        wrapper.last_attempts = 0
        return wrapper

    return decorator

